button { min-height: 42px; padding: 8px 15px; border: 0; border-radius: 6px; background: #3159a5; color: white; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #244783; }
button:focus-visible, input:focus-visible, a:focus-visible { outline: 3px solid #91b7ff; outline-offset: 2px; }
.project-list { display: grid; gap: 10px; }
.task-list { display: grid; gap: 10px; margin-top: 16px; }
.task-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 16px; border: 1px solid #dce1eb; border-radius: 8px; background: white; }
.task-row input[type="checkbox"] { width: 20px; height: 20px; accent-color: #3159a5; }
select { min-height: 42px; padding: 8px 11px; border: 1px solid #aeb8c9; border-radius: 6px; background: white; font: inherit; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 16px; border: 1px solid #dce1eb; border-radius: 8px; background: white; font-weight: 600; }
.alert { margin: 0 0 16px; color: #9c2424; }
@media (max-width: 480px) { .create-form { grid-template-columns: 1fr; } .create-form label { grid-column: auto; } .project-row { align-items: flex-start; flex-direction: column; } }

